"$HORIZON_BIN" inbox list --status open --json 2>/dev/null | python3 -c "
import json,sys,re
d=json.load(sys.stdin); its=d.get('items',d)
def txt(it):
    s=(it.get('title') or '')+' '+(it.get('body') or '')
    for c in (it.get('comments') or []): s+=' '+(c.get('body') or '')
    return s
print('=== open items mentioning uniform cotangent/embedding-dim bound ===')
for it in its:
    t=txt(it)
    if re.search(r'uniform (cotangent|bound|embedding)|uniform.{0,25}cotangent', t, re.I):
        print(' ',it['id'], it.get('kind'), '|', (it.get('title') or t[:100]).replace(chr(10),' ')[:120])
print()
print('=== open items mentioning rr.principal / front (d) ===')
for it in its:
    t=txt(it)
    if re.search(r'rr\.principal|front \(d\)|degree.zero.of.principal', t, re.I):
        print(' ',it['id'], it.get('kind'), '|', (it.get('title') or t[:100]).replace(chr(10),' ')[:120])
print()
print('=== open items mentioning Pic0Dimension / topologicalKrullDim ===')
for it in its:
    t=txt(it)
    if re.search(r'Pic0Dimension|topologicalKrullDim|EmbeddingDimensionBound', t):
        print(' ',it['id'], it.get('kind'), '|', (it.get('title') or t[:100]).replace(chr(10),' ')[:120])
"
